create extension if not exists pgcrypto;
create table public.workspaces(id uuid primary key default gen_random_uuid(),name text not null check(length(trim(name)) between 1 and 120),created_at timestamptz not null default now());
create table public.workspace_members(workspace_id uuid not null references public.workspaces(id) on delete cascade,user_id uuid not null references auth.users(id) on delete cascade,role text not null check(role in('owner','admin','member','viewer')),created_at timestamptz not null default now(),primary key(workspace_id,user_id));
create table public.projects(id uuid primary key default gen_random_uuid(),workspace_id uuid not null references public.workspaces(id) on delete restrict,name text not null check(length(trim(name)) between 1 and 160),description text not null default '',status text not null default 'Planning' check(status in('Active','Planning','On hold','Completed')),created_by uuid references auth.users(id) on delete set null,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.tasks(id uuid primary key default gen_random_uuid(),project_id uuid not null references public.projects(id) on delete restrict,title text not null check(length(trim(title)) between 1 and 160),description text not null default '',priority text not null default 'Medium' check(priority in('Low','Medium','High')),status text not null default 'To do' check(status in('To do','In progress','Blocked','Completed')),due_date date,assigned_to uuid references auth.users(id) on delete set null,created_by uuid references auth.users(id) on delete set null,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.agent_events(id uuid primary key default gen_random_uuid(),workspace_id uuid not null references public.workspaces(id) on delete restrict,task_id uuid references public.tasks(id) on delete set null,event_type text not null,message text not null,simulated boolean not null default true check(simulated=true),created_at timestamptz not null default now());
create table public.approval_requests(id uuid primary key default gen_random_uuid(),workspace_id uuid not null references public.workspaces(id) on delete restrict,requested_action text not null,status text not null default 'Pending' check(status in('Pending','Approved','Rejected','Cancelled')),requester_id uuid references auth.users(id) on delete set null,reviewer_id uuid references auth.users(id) on delete set null,decision_note text,created_at timestamptz not null default now(),decided_at timestamptz);
create table public.audit_events(id uuid primary key default gen_random_uuid(),workspace_id uuid not null references public.workspaces(id) on delete restrict,actor_id uuid references auth.users(id) on delete set null,event_type text not null,target_type text not null,target_id uuid,metadata jsonb not null default '{}'::jsonb,created_at timestamptz not null default now());
create index workspace_members_user_idx on public.workspace_members(user_id);
create index projects_workspace_idx on public.projects(workspace_id,created_at desc);
create index tasks_project_status_idx on public.tasks(project_id,status);
create index events_workspace_idx on public.agent_events(workspace_id,created_at desc);
create index approvals_workspace_status_idx on public.approval_requests(workspace_id,status,created_at desc);
create index audit_workspace_created_idx on public.audit_events(workspace_id,created_at desc);
alter table public.workspaces enable row level security;alter table public.workspace_members enable row level security;alter table public.projects enable row level security;alter table public.tasks enable row level security;alter table public.agent_events enable row level security;alter table public.approval_requests enable row level security;alter table public.audit_events enable row level security;
revoke all on public.workspaces,public.workspace_members,public.projects,public.tasks,public.agent_events,public.approval_requests,public.audit_events from anon;
grant select on public.workspaces,public.workspace_members,public.projects,public.tasks,public.agent_events,public.approval_requests,public.audit_events to authenticated;
grant insert,update,delete on public.projects,public.tasks to authenticated;grant insert on public.agent_events,public.approval_requests to authenticated;revoke insert,update,delete,truncate,references,trigger on public.audit_events from anon,authenticated;
create or replace function public.is_workspace_member(target_workspace uuid) returns boolean language sql stable security definer set search_path='' as $$ select exists(select 1 from public.workspace_members wm where wm.workspace_id=target_workspace and wm.user_id=(select auth.uid())); $$;
revoke all on function public.is_workspace_member(uuid) from public;grant execute on function public.is_workspace_member(uuid) to authenticated;
create policy "member reads workspace" on public.workspaces for select to authenticated using(public.is_workspace_member(id));
create policy "member reads memberships" on public.workspace_members for select to authenticated using(public.is_workspace_member(workspace_id));
create policy "member reads projects" on public.projects for select to authenticated using(public.is_workspace_member(workspace_id));
create policy "members read tasks" on public.tasks for select to authenticated using(exists(select 1 from public.projects p where p.id=tasks.project_id and public.is_workspace_member(p.workspace_id)));
create policy "members read events" on public.agent_events for select to authenticated using(public.is_workspace_member(workspace_id));
create policy "members add simulated events" on public.agent_events for insert to authenticated with check(simulated=true and public.is_workspace_member(workspace_id));
create policy "members read approvals" on public.approval_requests for select to authenticated using(public.is_workspace_member(workspace_id));
create policy "members create approvals" on public.approval_requests for insert to authenticated with check(public.is_workspace_member(workspace_id) and (requester_id is null or requester_id=(select auth.uid())));
create policy "members read audit" on public.audit_events for select to authenticated using(public.is_workspace_member(workspace_id));
-- Write policies for project/task and trusted approval/audit workflows are intentionally not enabled until role-specific tests are ready.
